export type CheckpointAttachmentKind = (typeof CHECKPOINT_ATTACHMENT_KINDS)[number];

export interface CheckpointAttachmentBinding {
  kind: CheckpointAttachmentKind;
  ref: string;
  contentHash: string;
  owner: string;
  /** Absolute expiry time in milliseconds since the Unix epoch. */
  expiresAt: number;
}

export interface CheckpointAttachmentCandidate {
  kind: CheckpointAttachmentKind;
  ref: string;
  contentHash?: string | null;
  owner?: string | null;
  /** Absolute expiry time in milliseconds since the Unix epoch. */
  expiresAt?: number | null;
}

export type CheckpointAttachmentRepairStatus =
  | "recovered"
  | "missing-hash"
  | "invalid-hash"
  | "missing-owner"
  | "expired"
  | "conflict";

export interface CheckpointAttachmentRepair {
  kind: CheckpointAttachmentKind;
  ref: string;
  contentHash: string | null;
  owner: string | null;
  expiresAt: number | null;
  status: CheckpointAttachmentRepairStatus;
  /** The hash retained for a conflicting reference, or null for an invalid binding. */
  retainedContentHash?: string;
}

export interface RecoveredCheckpointAttachment {
  kind: CheckpointAttachmentKind;
  ref: string;
  contentHash: string;
  owner: string;
  expiresAt: number;
}

export interface CheckpointAttachmentRecovery {
  recovered: RecoveredCheckpointAttachment[];
  repairs: CheckpointAttachmentRepair[];
  digest: string;
}

export interface CheckpointAttachmentRecoveryOptions {
  /** Evaluation time. It must be supplied for deterministic recovery. */
  now?: number;
}

const SHA256_HEX = /^[a-f0-9]{64}$/i;

function isKind(value: unknown): value is CheckpointAttachmentKind {
  return typeof value === "string" &&
    (CHECKPOINT_ATTACHMENT_KINDS as readonly string[]).includes(value);
}

function isHash(value: unknown): value is string {
  return typeof value === "string" && SHA256_HEX.test(value);
}

function nonEmpty(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function canonical(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonical).join(",")}]`;
  }
  const record = value as Record<string, unknown>;
  const keys = Object.keys(record).sort();
  return `{${keys.map((key) => `${JSON.stringify(key)}:${canonical(record[key])}`).join(",")}}`;
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function candidateKey(candidate: CheckpointAttachmentCandidate): string {
  return `${candidate.kind}\u0000${candidate.ref}`;
}

/**
 * Recover checkpoint attachments without mutating the candidates and without executing
 * attachment-dependent effects. Invalid or incomplete candidates are returned as
 * explicit repairs and are never included in `recovered`.
 */
export function recoverCheckpointAttachments(
  candidates: readonly CheckpointAttachmentCandidate[],
  options: CheckpointAttachmentRecoveryOptions = {},
): CheckpointAttachmentRecovery {
  const now = options.now;
  if (!Number.isFinite(now)) {
    throw new TypeError("A finite `now` timestamp is required for deterministic recovery");
  }

  const repairs: CheckpointAttachmentRepair[] = [];
  const recoveredByKey = new Map<string, RecoveredCheckpointAttachment>();

  for (const candidate of candidates) {
    if (!isKind(candidate.kind)) {
      throw new TypeError("Unsupported checkpoint attachment kind");
    }
    if (!nonEmpty(candidate.ref)) {
      throw new TypeError("Checkpoint attachment ref must be a non-empty string");
    }

    const ref = candidate.ref;
    const hash = candidate.contentHash;
    const owner = candidate.owner;
    const expiresAt = candidate.expiresAt;
    const base = {
      kind: candidate.kind,
      ref,
      contentHash: isHash(hash) ? hash.toLowerCase() : null,
      owner: nonEmpty(owner) ? owner : null,
      expiresAt: Number.isFinite(expiresAt) ? expiresAt : null,
    };

    if (hash === undefined || hash === null || hash === "") {
      repairs.push({ ...base, status: "missing-hash" });
      continue;
    }
    if (!isHash(hash)) {
      repairs.push({ ...base, status: "invalid-hash" });
      continue;
    }
    if (!nonEmpty(owner)) {
      repairs.push({ ...base, status: "missing-owner" });
      continue;
    }
    if (!Number.isFinite(expiresAt) || expiresAt! <= now) {
      repairs.push({ ...base, status: "expired" });
      continue;
    }

    const key = candidateKey(candidate);
    const existing = recoveredByKey.get(key);
    if (existing) {
      if (existing.contentHash !== base.contentHash) {
        repairs.push({
          ...base,
          status: "conflict",
          retainedContentHash: existing.contentHash,
        });
      }
      // Equal ref/hash bindings are idempotent duplicates. Equal refs with
      // different hashes above are explicitly rejected.
      continue;
    }

    recoveredByKey.set(key, {
      kind: candidate.kind,
      ref,
      contentHash: base.contentHash,
      owner: base.owner!,
      expiresAt: base.expiresAt!,
    });
  }

  const recovered = [...recoveredByKey.values()].sort((left, right) => {
    const kindOrder = compareText(left.kind, right.kind);
    return kindOrder || compareText(left.ref, right.ref);
  });
  const sortedRepairs = repairs.sort((left, right) => {
    const kindOrder = compareText(left.kind, right.kind);
    const refOrder = compareText(left.ref, right.ref);
    const statusOrder = compareText(left.status, right.status);
    return kindOrder || refOrder || statusOrder;
  });

  return {
    recovered,
    repairs: sortedRepairs,
    digest: sha256(canonical({ recovered, repairs: sortedRepairs })),
  };
}

/** Backwards-compatible concise alias for callers that use recovery terminology. */
export const recoverAttachmentBindings = recoverCheckpointAttachments;
"},{"path":"harness/specs/tasks/harness-gap-checkpoint-attachment-binding.md","content":"# Harness gap: checkpoint attachment binding (L04)

## Contract

Persistent checkpoint attachments are restricted to these five kinds:\n
- `task-attachment`
- `recovery-instruction`
- `context`
- `external-artifact-ref`
- `ledger-checkpoint`

Arbitrary cursors and blobs are not persistent attachment kinds.

Each binding is identified by its kind and reference (`ref`). A valid binding has:

- a lowercase or uppercase SHA-256 hexadecimal content hash;
- a non-empty owner;
- an absolute `expiresAt` timestamp in Unix epoch milliseconds.

Recovery evaluates expiry against the caller-provided `now` value. The absence of a deterministic evaluation time is an error.

## Repair states

Every invalid candidate is represented in `repairs` and excluded from `recovered`:

- `missing-hash`: no content hash was supplied;
- `invalid-hash`: the hash is not a 64-character SHA-256 hexadecimal string;
- `missing-owner`: no non-empty owner was supplied;
- `expired`: expiry is absent, invalid, or no later than `now`;
- `conflict`: the same kind and ref has already been recovered with a different hash.

The first valid binding for a kind/ref is retained. A conflict repair includes `retainedContentHash`. Identical kind/ref/hash occurrences are deduplicated. A later duplicate with a different owner or expiry does not replace the first valid binding.

## Purity and determinism

`recoverCheckpointAttachments` does not modify its input, invoke callbacks, load referenced data, run commands, or otherwise cause effects. Recovery only validates and selects already-supplied metadata.

`recovered` and `repairs` are deterministically sorted. `digest` is the SHA-256 digest of the canonical JSON representation of the sorted result. Repeating recovery with the same candidates and `now` returns the same digest.

## Required scenarios

1. All five supported kinds can be recovered.
2. An unsupported kind and an empty reference are rejected.
3. Missing, malformed, and non-hex hashes produce their respective repair states.
4. A missing owner and an expired binding produce their respective repair states.
5. Invalid and expired bindings do not appear in `recovered`.
6. Equal kind/ref/hash duplicates occur once in `recovered` and do not change the digest.
7. A different hash for the same kind/ref creates a `conflict` repair and retains the first hash.
8. The input array and candidate objects remain unchanged after recovery.
9. The result is stable across repeated calls.
